/* ===== UTILITY FUNCTIONS ===== */
function t(k){return T[S.lang][k]||k;}
function deepCopy(v){return JSON.parse(JSON.stringify(v));}
function apiToken(){
  try{return localStorage.getItem('dof_api_token')||'';}catch(e){return'';}
}
function setApiToken(token){
  try{
    if(token)localStorage.setItem('dof_api_token',token);
    else localStorage.removeItem('dof_api_token');
  }catch(e){}
}
function saveApiProfile(profile){
  try{
    if(profile)localStorage.setItem('dof_api_profile',JSON.stringify(profile));
    else localStorage.removeItem('dof_api_profile');
  }catch(e){}
}
function readApiProfile(){
  try{
    var raw=localStorage.getItem('dof_api_profile');
    return raw?JSON.parse(raw):null;
  }catch(e){return null;}
}
function authUser(){
  var p=readApiProfile();
  return p?normalizeProfile(p):S.user;
}
async function apiRequest(path,options){
  options=options||{};
  var headers=options.headers||{};
  headers['Content-Type']=headers['Content-Type']||'application/json';
  var token=apiToken();
  if(token)headers.Authorization='Bearer '+token;
  var res=await fetch(path,{method:options.method||'GET',headers:headers,body:options.body?JSON.stringify(options.body):undefined});
  var text=await res.text();
  var data=text?JSON.parse(text):{};
  if(!res.ok){
    var msg=(data.error&&data.error.message)||'Request failed';
    throw new Error(msg);
  }
  return data;
}
function normalizeProfile(profile){
  if(!profile)return null;
  var pp=Array.isArray(profile.photographer_profiles)?profile.photographer_profiles[0]:profile.photographer_profiles;
  return {
    id:profile.id,email:profile.email,role:profile.role,
    name:profile.display_name||profile.name||'',
    nameAr:profile.display_name||profile.nameAr||profile.name||'',
    phone:profile.phone||'',avatar:profile.avatar_url||profile.avatar||'https://picsum.photos/seed/avatar1/80/80',
    specialty:pp?(pp.specialty||'Photography'):(profile.specialty||'Photography'),
    specialtyAr:pp?(pp.specialty||'تصوير'):(profile.specialtyAr||'تصوير'),
    region:pp?(pp.region||'cairo'):(profile.region||'cairo'),
    regionAr:pp?(pp.region||'القاهرة'):(profile.regionAr||'القاهرة'),
    customLink:pp?(pp.custom_link||''):(profile.customLink||''),
    bio:pp?(pp.bio||''):(profile.bio||''),
    bioAr:pp?(pp.bio||''):(profile.bioAr||''),
    cover:pp?(pp.cover_url||'https://picsum.photos/seed/cover1/800/400'):(profile.cover||'https://picsum.photos/seed/cover1/800/400'),
    social:pp?(pp.social_links||{}):(profile.social||{}),
    rating:profile.rating||0,bookings:profile.booking_count||0,
    subscriptionDueAt:pp?pp.subscription_due_at:null,
    portfolioSuspended:pp?pp.is_suspended===true:false,
    isSubscribed:pp?pp.subscription_status==='active':false
  };
}
function normalizeDirectoryPhotographer(row){
  return {
    id:row.id,name:row.display_name,nameAr:row.display_name,
    specialty:row.specialty||'Photography',specialtyAr:row.specialty||'تصوير',
    region:row.region||'',regionAr:row.region||'',customLink:row.custom_link,
    avatar:row.avatar_url||'https://picsum.photos/seed/photog'+row.id+'/200/200',
    cover:row.cover_url||'https://picsum.photos/seed/cover'+row.id+'/800/400',
    bio:row.bio||'',bioAr:row.bio||'',social:row.social_links||{},
    rating:row.rating||0,bookings:row.booking_count||0,packages:[],portfolio:[]
  };
}
function normalizePackage(pkg){
  return {
    id:pkg.id,name:pkg.name,nameAr:pkg.name,description:pkg.description||'',descriptionAr:pkg.description||'',
    price:Math.round(Number(pkg.price_cents||0)/100),duration:String(pkg.duration_minutes||60)+' minutes',
    durationAr:String(pkg.duration_minutes||60)+' دقيقة',durationMinutes:pkg.duration_minutes||60,
    features:Array.isArray(pkg.features)?pkg.features:[],featuresAr:Array.isArray(pkg.features)?pkg.features:[],
    files:Array.isArray(pkg.attachments)?pkg.attachments:[],status:pkg.status||'active',featured:pkg.featured===true
  };
}
function normalizeBooking(b){
  var pkg=b.packages||{};
  return {
    id:b.id,clientName:b.client_name||'',clientEmail:b.client_email||'',clientPhone:b.client_phone||'',
    date:b.booking_date,time:(b.start_time||'').slice(0,5),endTime:(b.end_time||'').slice(0,5),
    serviceId:b.package_id,service:pkg.name||b.service||'',servicePrice:Math.round(Number(b.price_cents||0)/100),
    serviceDuration:String(pkg.duration_minutes||'')+' minutes',status:b.status||'confirmed',
    photographerName:b.photographerName||'',photographerAvatar:b.photographerAvatar||''
  };
}
function normalizeConversation(c){
  return {
    id:c.id,photographerId:c.photographer_id,clientId:c.client_id,clientName:c.client_name||'Client',
    photographerAvatar:c.photographer_avatar||'https://picsum.photos/seed/conv/80/80',
    lastMessage:c.last_message||'',lastMessageAt:c.last_message_at||c.created_at,unread:c.unread||0,
    status:(c.archived_by||[]).indexOf(authUser()&&authUser().id)>-1?'archived':'active',blockedBy:c.blocked_by||null
  };
}
function normalizeMessage(m,conv){
  var sender=m.sender_id===conv.photographerId?'photographer':'client';
  return {id:m.id,conversationId:m.conversation_id,sender:sender,content:m.content,timestamp:m.created_at,deleted:m.is_deleted===true};
}
function durationToMinutes(value){
  if(!value)return 60;
  var s=String(value).toLowerCase();
  var n=parseFloat(s);
  if(!n||isNaN(n))return 60;
  if(s.indexOf('hour')>-1||s.indexOf('ساعة')>-1||s.indexOf('ساع')>-1)return Math.round(n*60);
  return Math.round(n);
}
async function refreshMyPackages(){
  if(!apiToken()||!S.user||S.user.role!=='photographer')return;
  var data=await apiRequest('/api/packages');
  S.packages=(data.packages||[]).map(normalizePackage);
}
async function refreshMyBookings(){
  if(!apiToken()||!S.user)return;
  var data=await apiRequest('/api/bookings');
  S.bookings=(data.bookings||[]).map(normalizeBooking);
  S.appointments=S.bookings.filter(function(b){return b.status==='confirmed';}).map(function(b){
    return {id:b.id,date:b.date,time:b.time,client:b.clientName,service:b.service,status:b.status,notes:''};
  });
}
async function refreshMyPortfolio(){
  if(!apiToken()||!S.user||S.user.role!=='photographer'||!S.user.customLink)return;
  var data=await apiRequest('/api/photographers/'+encodeURIComponent(S.user.customLink));
  S.portfolio=[];
  (data.collections||[]).forEach(function(col){
    (col.portfolio_photos||[]).forEach(function(photo){S.portfolio.push({id:photo.id,url:photo.url,title:photo.title||''});});
  });
  S.portfolioPublished=deepCopy(S.portfolio);
}
async function refreshWorkingHours(){
  if(!apiToken()||!S.user||S.user.role!=='photographer')return;
  var data=await apiRequest('/api/availability/working-hours');
  S.workingHours=(data.workingHours||[]).map(function(row){
    return {dayOfWeek:row.day_of_week,startTime:String(row.start_time||'08:00').slice(0,5),endTime:String(row.end_time||'14:00').slice(0,5),enabled:row.enabled!==false};
  });
}
async function hydrateAuthenticatedState(){
  if(!apiToken())return;
  try{
    var me=await apiRequest('/api/me');
    S.user=normalizeProfile(me.profile);
    saveApiProfile(me.profile);
    if(S.user&&S.user.role==='photographer'){
      await refreshMyPackages();
      await refreshMyPortfolio().catch(function(){});
      await refreshWorkingHours().catch(function(){});
      await refreshMyBookings();
    } else if(S.user&&S.user.role==='client'){
      await refreshMyBookings();
    }
  }catch(e){
    setApiToken('');
    saveApiProfile(null);
  }
  updateNavBar();
}
function saveFrontendSession(){
  try{
    sessionStorage.setItem('dof_frontend_session_v1',JSON.stringify({
      user:S.user,appointments:S.appointments,bookings:S.bookings,portfolio:S.portfolio,
      portfolioPublished:S.portfolioPublished,packages:S.packages,workingHours:S.workingHours,lang:S.lang,tab:S.tab
    }));
  }catch(e){}
}
function restoreFrontendSession(){
  try{
    var raw=sessionStorage.getItem('dof_frontend_session_v1');
    if(!raw)return;
    var data=JSON.parse(raw);
    if(data.lang)S.lang=data.lang;
    if(data.tab)S.tab=data.tab;
    if(data.user)S.user=data.user;
    if(data.appointments)S.appointments=data.appointments;
    if(data.bookings)S.bookings=data.bookings;
    if(data.portfolio)S.portfolio=data.portfolio;
    if(data.portfolioPublished)S.portfolioPublished=data.portfolioPublished;
    if(data.packages)S.packages=data.packages;
    if(data.workingHours)S.workingHours=data.workingHours;
  }catch(e){}
}
function hashPII(value){
  var s=String(value||'');
  var h=5381;
  for(var i=0;i<s.length;i++){h=((h<<5)+h)+s.charCodeAt(i);}
  return 'h'+(h>>>0).toString(16);
}
function persistCustomerVault(){
  try{
    localStorage.setItem('dof_customer_vault_v1',JSON.stringify(S.customerVault||[]));
  }catch(e){}
}
function addCustomerRecord(booking){
  var rec={
    bookingId:booking.id,
    createdAt:new Date().toISOString(),
    clientName:booking.clientName||'',
    clientEmailHash:hashPII((booking.clientEmail||'').toLowerCase().trim()),
    clientPhoneHash:hashPII(booking.clientPhone||''),
    photographerName:booking.photographerName||'',
    service:booking.service||'',
    date:booking.date||'',
    time:booking.time||'',
    status:booking.status||'pending'
  };
  if(!S.customerVault)S.customerVault=[];
  S.customerVault.push(rec);
  if(S.customerVault.length>300){S.customerVault=S.customerVault.slice(-300);}
  persistCustomerVault();
}
function checkSubscriptionStatus(){
  if(!S.user||S.user.role!=='photographer')return;
  if(!S.subscriptionDueAt)return;
  var now=Date.now();
  var dueMs=new Date(S.subscriptionDueAt).getTime();
  if(!dueMs||isNaN(dueMs))return;
  var overdue=now-dueMs;
  if(overdue<=0){S.portfolioSuspended=false;S.paymentWarningSentAt=null;return;}
  if(overdue<=24*60*60*1000){
    if(!S.paymentWarningSentAt){
      S.paymentWarningSentAt=new Date().toISOString();
      showToast(S.lang==='ar'?'تنبيه: متبقي أقل من 24 ساعة قبل إيقاف البرتفوليو لعدم السداد':'Warning: less than 24 hours before portfolio suspension due to non-payment','error');
    }
    S.portfolioSuspended=false;
    return;
  }
  S.portfolioSuspended=true;
}
function gf(p,f){return S.lang==='ar'?(p[f+'Ar']||p[f]):p[f];}
function fmtD(ds){if(!ds)return'';var d=new Date(ds+'T00:00:00');return S.lang==='ar'?d.toLocaleDateString('ar-SA',{year:'numeric',month:'long',day:'numeric'}):d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});}
function statusBadge(st){var m={pending:'badge-pending',confirmed:'badge-confirmed',cancelled:'badge-cancelled'};var l={pending:t('pending'),confirmed:t('confirmed'),cancelledStatus:t('cancelledStatus')};return'<span class="badge '+m[st]+'">'+(l[st]||st)+'</span>';}
var TIME_SLOTS_CACHE=null;
function timeSlots(){
  if(TIME_SLOTS_CACHE){return TIME_SLOTS_CACHE.slice();}
  var s=[];
  for(var h=8;h<=20;h++){var hr=h>12?h-12:h;var ap=h>=12?'PM':'AM';s.push(hr+':00 '+ap);}
  TIME_SLOTS_CACHE=s;
  return s.slice();
}
function debounce(fn,wait){
  var timer;
  return function(){
    var args=arguments,ctx=this;
    clearTimeout(timer);
    timer=setTimeout(function(){fn.apply(ctx,args);},wait);
  };
}
var debouncedExploreSearch=debounce(function(val){updateExploreFilter('search',val);},180);
function starsHTML(r){if(!r)return'';var full=Math.floor(r),half=r%1>=0.5?1:0,empty=5-full-half;var s='';for(var i=0;i<full;i++)s+='<i class="fas fa-star"></i>';if(half)s+='<i class="fas fa-star-half-alt"></i>';for(var i=0;i<empty;i++)s+='<i class="fas fa-star empty"></i>';return s;}
function validateEmail(e){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);}
function formatMoney(v,currency){
  var amount=Number(v||0);
  if(S.lang==='ar'){
    return amount.toLocaleString('ar-EG',{style:'currency',currency:'EGP',maximumFractionDigits:0});
  }
  return amount.toLocaleString() + ' EGP';
}

function formatPrice(v){
  var amount=Number(v||0);
  if(S.lang==='ar'){
    return amount.toLocaleString('ar-EG')+' ج.م';
  }
  return amount.toLocaleString() + ' EGP';
}
function getPackageById(id){
  return (S.packages||[]).find(function(p){return String(p.id)===String(id);})||null;
}
function formatFileSize(bytes){if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}
function getFileIcon(filename){var ext=filename.split('.').pop().toLowerCase();if(ext==='pdf')return'fa-file-pdf';if(['jpg','jpeg','png'].indexOf(ext)>-1)return'fa-file-image';return'fa-file';}

/* ===== TOAST NOTIFICATION SYSTEM ===== */
function showToast(msg,type){
  type=type||'info';var c=document.getElementById('toast-container');
  if(!c)return;
  var icons={success:'fa-check-circle',error:'fa-exclamation-circle',info:'fa-info-circle'};
  var el=document.createElement('div');el.className='toast '+type;
  var icon=document.createElement('i');icon.className='fas '+icons[type];
  var text=document.createElement('span');text.textContent=String(msg||'');
  el.appendChild(icon);el.appendChild(text);
  c.appendChild(el);
  setTimeout(function(){el.style.opacity='0';el.style.transform='translateX(40px)';el.style.transition='all .3s';setTimeout(function(){el.remove();},300);},3500);
}

/* ===== MODAL OPEN/CLOSE ===== */
function openModal(id){var m=document.getElementById(id);if(!m)return;m.classList.add('active');document.body.style.overflow='hidden';}
function closeModal(id){var m=document.getElementById(id);if(!m)return;m.classList.remove('active');document.body.style.overflow='';}
/* Close modal on backdrop click or Escape */
document.querySelectorAll('.modal-overlay').forEach(function(ov){
  ov.addEventListener('click',function(e){if(e.target===ov){ov.classList.remove('active');document.body.style.overflow='';}});
});
document.addEventListener('keydown',function(e){
  if(e.key==='Escape'){document.querySelectorAll('.modal-overlay.active').forEach(function(m){m.classList.remove('active');document.body.style.overflow='';});}
});

/* ===== AUTH SYSTEM ===== */
function switchAuthTab(tab){
  document.getElementById('login-form').classList.toggle('hidden',tab!=='login');
  document.getElementById('register-form').classList.toggle('hidden',tab!=='register');
  document.querySelectorAll('.auth-tab').forEach(function(btn,i){
    var act=(i===0&&tab==='login')||(i===1&&tab==='register');
    btn.classList.toggle('active',act);btn.classList.toggle('border-[var(--accent)]',act);
    btn.classList.toggle('text-[var(--accent)]',act);btn.classList.toggle('border-transparent',!act);
    btn.classList.toggle('text-[var(--text2)]',!act);
  });
}
function selectRole(role,el){
  S.regRole=role;
  document.querySelectorAll('.role-option').forEach(function(e){e.classList.remove('selected');});
  el.classList.add('selected');
  document.getElementById('photo-fields').classList.toggle('hidden',role!=='photographer');
  document.getElementById('client-fields').classList.toggle('hidden',role!=='client');
}
function togglePassVis(id,btn){
  var inp=document.getElementById(id);
  if(inp.type==='password'){inp.type='text';btn.innerHTML='<i class="fas fa-eye-slash"></i>';}
  else{inp.type='password';btn.innerHTML='<i class="fas fa-eye"></i>';}
}
function validateLink(inp){inp.value=inp.value.toLowerCase().replace(/[^a-z0-9-]/g,'');}
function checkPassStrength(val){
  var bar=document.getElementById('pass-strength'),hint=document.getElementById('pass-hint');
  if(!val){bar.classList.add('hidden');return;}
  bar.classList.remove('hidden','weak','medium','strong');
  var score=0;
  if(val.length>=8)score++;if(/[0-9]/.test(val))score++;if(/[!@#$%^&*]/.test(val))score++;if(/[A-Z]/.test(val))score++;
  if(score<=1){bar.classList.add('weak');hint.textContent=S.lang==='ar'?'ضعيفة':'Weak';hint.style.color='var(--danger)';}
  else if(score<=2){bar.classList.add('medium');hint.textContent=S.lang==='ar'?'متوسطة':'Medium';hint.style.color='var(--warn)';}
  else{bar.classList.add('strong');hint.textContent=S.lang==='ar'?'قوية':'Strong';hint.style.color='var(--success)';}
}
async function handleLogin(e){
  e.preventDefault();var email=document.getElementById('login-email').value;
  if(!validateEmail(email)){showToast(S.lang==='ar'?'بريد غير صالح':'Invalid email','error');return;}
  try{
    var pass=document.getElementById('login-pass').value;
    var data=await apiRequest('/api/auth/login',{method:'POST',body:{email:email,password:pass}});
    setApiToken(data.session&&data.session.access_token);
    saveApiProfile(data.profile);
    S.user=normalizeProfile(data.profile);
    if(S.user&&S.user.role==='photographer'){
      await refreshMyPackages();
      await refreshMyPortfolio().catch(function(){});
      await refreshWorkingHours().catch(function(){});
      await refreshMyBookings();
      closeModal('auth-modal');navigate('dashboard');
    } else {
      await refreshMyBookings().catch(function(){});
      closeModal('auth-modal');navigate('landing');
    }
    showToast(t('welcomeBack'),'success');
  }catch(err){
    showToast(err.message||'Login failed','error');
    return;
  }
  setupChatFAB();updateChatBadge();updateNavBar();
}
async function handleRegister(e){
  e.preventDefault();
  var name,spec,region,link,email,phone,pass;
  try{
    if(S.regRole==='photographer'){
      name=document.getElementById('reg-name').value;spec=document.getElementById('reg-spec').value;
      region=document.getElementById('reg-region').value;
      email=document.getElementById('reg-email').value;phone=document.getElementById('reg-phone').value;
      pass=document.getElementById('reg-pass').value;
      if(!name||!email||!phone||!pass){showToast('Fill required fields','error');return;}
      await apiRequest('/api/auth/register',{method:'POST',body:{
        role:'photographer',displayName:name,email:email,password:pass,phone:phone,
        specialty:spec||'Photography',region:region||'cairo',customLink:email.split('@')[0]
      }});
    } else {
      name=document.getElementById('reg-client-name').value;
      email=document.getElementById('reg-email').value;phone=document.getElementById('reg-phone').value;
      pass=document.getElementById('reg-pass').value;
      if(!name||!email||!phone||!pass){showToast('Fill required fields','error');return;}
      await apiRequest('/api/auth/register',{method:'POST',body:{role:'client',displayName:name,email:email,password:pass,phone:phone}});
    }
    var loginData=await apiRequest('/api/auth/login',{method:'POST',body:{email:email,password:pass}});
    setApiToken(loginData.session&&loginData.session.access_token);
    saveApiProfile(loginData.profile);
    S.user=normalizeProfile(loginData.profile);
    closeModal('auth-modal');
    if(S.user.role==='photographer'){S.appointments=[];S.bookings=[];S.portfolio=[];S.packages=[];S.portfolioPublished=[];navigate('dashboard');}
    else{S.bookings=[];navigate('landing');}
  }catch(err){
    showToast(err.message||'Registration failed','error');
    return;
  }
  showToast('تم إنشاء الحساب!','success');
  setupChatFAB();updateChatBadge();updateNavBar();
}
function handleLogout(){S.user=null;S.portfolio=[];S.portfolioPublished=[];S.portfolioDirty=false;S.isPortfolioPreview=false;
  try{sessionStorage.removeItem('dof_frontend_session_v1');}catch(e){}
  setApiToken('');saveApiProfile(null);
  var fab=document.getElementById('chat-fab');if(fab)fab.classList.add('hidden');
  if(document.getElementById('chat-panel'))document.getElementById('chat-panel').classList.remove('open');
  updateChatBadge();updateNavBar();navigate('landing');showToast('تم تسجيل الخروج','info');
}

/* ===== LANGUAGE TOGGLE ===== */
function toggleLang(){
  S.lang=S.lang==='en'?'ar':'en';
  document.documentElement.lang=S.lang;
  document.documentElement.dir=S.lang==='ar'?'rtl':'ltr';
  document.querySelectorAll('[data-t]').forEach(function(el){
    var k=el.getAttribute('data-t');if(T[S.lang][k])el.textContent=T[S.lang][k];});
  var nb=S.lang==='en'?'AR':'EN';
  document.querySelectorAll('#lang-btn,#lang-btn-exp,#lang-btn-dash,#lang-btn-pub').forEach(function(b){b.textContent=nb;});
  var pkgLabel=document.getElementById('sidebar-packages-label');
  if(pkgLabel){pkgLabel.textContent=S.lang==='ar'?'الباقات':'Packages';}
  var subPrice=document.getElementById('sub-price-label');
  if(subPrice){subPrice.innerHTML=S.lang==='ar'?'200 <span class="text-lg font-normal">ج.م</span> <span class="text-base text-[var(--text2)] font-normal">/ شهريًا</span>':'200 <span class="text-lg font-normal">EGP</span> <span class="text-base text-[var(--text2)] font-normal">/ month</span>';}
  var pricingPlan=document.getElementById('pricing-plan-price');
  if(pricingPlan){pricingPlan.innerHTML=S.lang==='ar'?'200 <span class="text-lg font-normal">ج.م</span><span class="text-base text-[var(--text2)] font-normal"> / شهريًا</span>':'200 <span class="text-lg font-normal">EGP</span><span class="text-base text-[var(--text2)] font-normal"> / month</span>';}
  var paymentLabel=document.getElementById('payment-method-label');
  if(paymentLabel){paymentLabel.textContent=S.lang==='ar'?'طريقة الدفع':'Payment Method';}
  /* Update chat UI labels */
  var sidebarChatLabel=document.getElementById('sidebar-chat-label');
  if(sidebarChatLabel){sidebarChatLabel.textContent=S.lang==='ar'?'الرسائل':'Messages';}
  var chatPanelTitle=document.getElementById('chat-panel-title');
  if(chatPanelTitle){chatPanelTitle.textContent=S.chatActiveConv?t('convWith')+' '+(S.conversations.find(function(c){return c.id===S.chatActiveConv;})||{}).clientName:t('chatTitle');}
  if(S.chatActiveConv)renderChatMessages();
  else renderChatConvList();
  updateChatBadge();
  if(S.view==='explore')renderExplorePage();
  else if(S.view==='dashboard')renderTab();
  else if(S.view==='public')renderPublicProfile();
  else if(S.view==='landing')renderClientBookingsPanel();
}

/* ===== NAVIGATION ===== */
var PAGE_URLS={landing:'index.html',explore:'explore.html',dashboard:'photographerdashboard.html',public:'publicprofile.html'};
function getPageView(){
  return (document.body&&document.body.dataset&&document.body.dataset.page)||'landing';
}
function hasPageContainer(v){
  var ids={landing:'landing-page',explore:'explore-page',dashboard:'dashboard-page',public:'public-page'};
  return !!document.getElementById(ids[v]);
}
function goToPage(v){
  var url=PAGE_URLS[v]||'homepage.html';
  saveFrontendSession();
  if(location.pathname.split('/').pop()!==url){window.location.href=url;}
}
function updateNavBar(){
  var u=S.user;
  var isClient=u&&u.role==='client';

  /* Landing nav */
  var btnStart=document.getElementById('nav-get-started');
  var btnOut=document.getElementById('nav-logout');
  var userName=document.getElementById('nav-user-name');
  var pricingLink=document.getElementById('nav-pricing-link');
  var pricingSection=document.getElementById('pricing-section');
  if(btnStart)btnStart.classList.toggle('hidden',!!u);
  if(btnOut){btnOut.classList.toggle('hidden',!u);if(userName&&u)userName.textContent=u.name||'';}
  if(pricingLink)pricingLink.classList.toggle('hidden',isClient);
  if(pricingSection)pricingSection.classList.toggle('hidden',isClient);

  /* Hero join btn — hide when logged in */
  var heroJoin=document.getElementById('hero-join-btn');
  if(heroJoin)heroJoin.classList.toggle('hidden',!!u);

  /* Explore nav */
  var btnStartExp=document.getElementById('nav-get-started-exp');
  var btnOutExp=document.getElementById('nav-logout-exp');
  var userNameExp=document.getElementById('nav-user-name-exp');
  if(btnStartExp)btnStartExp.classList.toggle('hidden',!!u);
  if(btnOutExp){btnOutExp.classList.toggle('hidden',!u);if(userNameExp&&u)userNameExp.textContent=u.name||'';}

  /* Public profile nav */
  var btnStartPub=document.getElementById('nav-get-started-pub');
  var btnOutPub=document.getElementById('nav-logout-pub');
  var userNamePub=document.getElementById('nav-user-name-pub');
  if(btnStartPub)btnStartPub.classList.toggle('hidden',!!u);
  if(btnOutPub){btnOutPub.classList.toggle('hidden',!u);if(userNamePub&&u)userNamePub.textContent=u.name||'';}
}
function navigate(v){
  checkSubscriptionStatus();
  if(!hasPageContainer(v)){goToPage(v);return;}
  S.view=v;
  var landing=document.getElementById('landing-page');
  var explore=document.getElementById('explore-page');
  var dashboard=document.getElementById('dashboard-page');
  var publicPage=document.getElementById('public-page');
  if(landing)landing.classList.toggle('hidden',v!=='landing');
  if(explore)explore.classList.toggle('hidden',v!=='explore');
  if(dashboard)dashboard.classList.toggle('hidden',v!=='dashboard');
  if(publicPage)publicPage.classList.toggle('hidden',v!=='public');
  if(v==='explore')renderExplorePage();
  else if(v==='dashboard'){renderTab();updateSidebarUser();}
  else if(v==='public')renderPublicProfile();
  updateNavBar();
  setupChatFAB();updateChatBadge();
  window.scrollTo(0,0);
  var sidebar=document.getElementById('sidebar');
  var overlay=document.getElementById('sidebar-overlay');
  if(sidebar)sidebar.classList.remove('open');
  if(overlay)overlay.classList.add('hidden');
}
function formatBookingDay(dateStr){
  if(!dateStr)return'';
  var d=new Date(dateStr+'T00:00:00');
  return S.lang==='ar'
    ? d.toLocaleDateString('ar-SA',{weekday:'long'})
    : d.toLocaleDateString('en-US',{weekday:'long'});
}
function renderClientBookingsPanel(){
  var panel=document.getElementById('client-bookings-section');
  var content=document.getElementById('client-bookings-content');
  var title=document.getElementById('client-bookings-title');
  var cta=document.getElementById('client-bookings-cta');
  if(!panel||!content)return;
  if(title){title.textContent=S.lang==='ar'?'حجوزاتي':'My Bookings';}
  if(cta){cta.textContent=S.lang==='ar'?'احجز جلسة جديدة':'Book New Session';}
  if(!S.user||S.user.role!=='client'){
    panel.classList.add('hidden');
    return;
  }
  panel.classList.remove('hidden');
  var items=(S.bookings||[]).slice().reverse();
  if(items.length===0){
    content.innerHTML='<p class="text-sm text-[var(--text2)]">'+(S.lang==='ar'?'لا توجد حجوزات حتى الآن. يمكنك البدء بحجز جديد من صفحة المصورين.':'No bookings yet. You can start by booking from the photographers page.')+'</p>';
    return;
  }
  content.innerHTML='<div class="space-y-3">'+items.map(function(b){
    return'<div class="p-4 rounded-xl bg-[var(--bg2)] border border-[var(--border)]">'+
      '<div class="flex flex-wrap items-center justify-between gap-3 mb-2">'+
      '<div class="font-semibold">'+(b.service||'-')+'</div>'+
      statusBadge(b.status||'pending')+'</div>'+
      '<div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-2 text-sm">'+
      '<div><span class="text-[var(--text2)]">'+(S.lang==='ar'?'اليوم: ':'Day: ')+'</span><span class="font-semibold">'+formatBookingDay(b.date)+'</span></div>'+
      '<div><span class="text-[var(--text2)]">'+(S.lang==='ar'?'التاريخ: ':'Date: ')+'</span><span class="font-semibold">'+fmtD(b.date)+'</span></div>'+
      '<div><span class="text-[var(--text2)]">'+(S.lang==='ar'?'الوقت: ':'Time: ')+'</span><span class="font-semibold">'+(b.time||'-')+'</span></div>'+
      '<div><span class="text-[var(--text2)]">'+(S.lang==='ar'?'المصور: ':'Photographer: ')+'</span><span class="font-semibold">'+(b.photographerName||'-')+'</span></div>'+
      '</div></div>';
  }).join('')+'</div>';
}

/* ===== DASHBOARD SIDEBAR ===== */
function updateSidebarUser(){
  if(!S.user)return;
  var avatar=document.getElementById('sidebar-avatar');
  var name=document.getElementById('sidebar-name');
  var spec=document.getElementById('sidebar-spec');
  if(avatar)avatar.src=S.user.avatar;
  if(name)name.textContent=gf(S.user,'name');
  if(spec)spec.textContent=gf(S.user,'specialty');
  var pct=Math.round((S.trialDaysLeft/7)*100);
  var trialText=document.getElementById('trial-text');
  var trialProgress=document.getElementById('trial-progress');
  if(trialText)trialText.textContent=S.trialDaysLeft+' '+t('daysRemaining');
  if(trialProgress)trialProgress.style.width=pct+'%';
}
function toggleSidebar(){var sidebar=document.getElementById('sidebar');var overlay=document.getElementById('sidebar-overlay');if(sidebar)sidebar.classList.toggle('open');if(overlay)overlay.classList.toggle('hidden');}
function switchTab(tab){
  S.tab=tab;
  document.querySelectorAll('.sidebar-link[data-tab]').forEach(function(el){el.classList.toggle('active',el.dataset.tab===tab);});
  if(tab==='chat'&&apiToken()){refreshConversations().then(function(){renderTab();}).catch(function(){});}
  renderTab();
  if(window.innerWidth<1024){var sidebar=document.getElementById('sidebar');var overlay=document.getElementById('sidebar-overlay');if(sidebar)sidebar.classList.remove('open');if(overlay)overlay.classList.add('hidden');}
}
function renderTab(){
  var c=document.getElementById('dash-content');
  if(!c)return;
  switch(S.tab){
    case'overview':c.innerHTML=renderOverview();break;
    case'portfolio':c.innerHTML=renderPortfolio();break;
    case'packages':c.innerHTML=renderPackages();break;
    case'calendar':c.innerHTML=renderCalendar();break;
    case'bookings':c.innerHTML=renderBookings();break;
    case'chat':c.innerHTML=renderChatDashboard();break;
    case'settings':c.innerHTML=renderSettings();break;
  }
}

