function filterPackages(filter){S.packageFilter=filter;renderTab();}
function sortPackages(sort){S.packageSort=sort;renderTab();}

function openPackageModal(editId){
  S.tempPackageFeatures=[];
  S.tempPackageFiles=[];
  document.getElementById('pkg-edit-id').value='';
  document.getElementById('package-form').reset();
  document.getElementById('pkg-features-list').innerHTML='';
  document.getElementById('pkg-files-list').innerHTML='';
  document.getElementById('pkg-preview-section').classList.add('hidden');
  
  /* Clear validation */
  document.querySelectorAll('.validation-msg').forEach(function(m){m.className='validation-msg';m.textContent='';});
  document.querySelectorAll('.input.error').forEach(function(i){i.classList.remove('error');});
  
  if(editId){
    var pkg=getPackageById(editId);
    if(pkg){
      document.getElementById('package-modal-title').textContent=t('editPackage');
      document.getElementById('pkg-submit-btn').textContent=t('savePackage');
      document.getElementById('pkg-edit-id').value=pkg.id;
      document.getElementById('pkg-name').value=pkg.name||'';
      document.getElementById('pkg-nameAr').value=pkg.nameAr||'';
      document.getElementById('pkg-desc').value=pkg.description||'';
      document.getElementById('pkg-descAr').value=pkg.descriptionAr||'';
      document.getElementById('pkg-price').value=pkg.price||'';
      document.getElementById('pkg-duration').value=pkg.duration||'';
      document.getElementById('pkg-durationAr').value=pkg.durationAr||'';
      document.getElementById('pkg-status').value=pkg.status||'active';
      document.getElementById('pkg-featured').checked=pkg.featured||false;
      
      /* Load features */
      S.tempPackageFeatures=(pkg.features||[]).map(function(f,i){return{en:f,ar:(pkg.featuresAr||[])[i]||f};});
      renderPackageFeatures();
      
      /* Load files info */
      S.tempPackageFiles=pkg.files||[];
      renderPackageFiles();
    }
  } else {
    document.getElementById('package-modal-title').textContent=t('addPackage');
    document.getElementById('pkg-submit-btn').textContent=t('savePackage');
  }
  
  openModal('package-modal');
}

function editPackage(id){openPackageModal(id);}

function deletePackage(id){
  S.deletePackageId=id;
  openModal('delete-modal');
}

async function confirmDeletePackage(){
  if(S.deletePackageId){
    try{
      if(apiToken()){
        await apiRequest('/api/packages/'+S.deletePackageId,{method:'DELETE'});
        await refreshMyPackages();
      } else {
        S.packages=S.packages.filter(function(p){return String(p.id)!==String(S.deletePackageId);});
      }
      syncPackagesToDirectory();
      closeModal('delete-modal');
      renderTab();
      showToast('Package deleted','info');
      S.deletePackageId=null;
    }catch(err){showToast(err.message||'Could not delete package','error');}
  }
}

function addPackageFeature(){
  var inputEn=document.getElementById('pkg-new-feature-en');
  var inputAr=document.getElementById('pkg-new-feature-ar');
  var valEn=inputEn.value.trim();
  var valAr=inputAr.value.trim();
  if(!valEn&&!valAr)return;
  
  S.tempPackageFeatures.push({
    en:valEn||valAr,
    ar:valAr||valEn
  });
  inputEn.value='';
  inputAr.value='';
  renderPackageFeatures();
  inputEn.focus();
}

function removePackageFeature(index){
  S.tempPackageFeatures.splice(index,1);
  renderPackageFeatures();
}

function renderPackageFeatures(){
  var container=document.getElementById('pkg-features-list');
  container.innerHTML=S.tempPackageFeatures.map(function(f,i){
    var showEn=f.en&&f.en!==f.ar;
    var showAr=f.ar&&f.ar!==f.en;
    return'<span class="feature-tag" style="padding:6px 10px;display:inline-flex;align-items:center;gap:6px;">'+
    '<i class="fas fa-check text-[var(--success)]" style="font-size:9px;"></i>'+
    (showEn?'<span class="text-xs" style="font-family:monospace;opacity:0.9;" dir="ltr">'+f.en+'</span>':'')+
    (showEn&&showAr?'<span class="text-xs" style="opacity:0.3;">|</span>':'')+
    (showAr?'<span class="text-xs" dir="rtl">'+f.ar+'</span>':'')+
    (!showEn&&!showAr?'<span class="text-xs">'+f.en+'</span>':'')+
    '<span class="remove-feature" onclick="removePackageFeature('+i+')" style="margin-left:2px;cursor:pointer;"><i class="fas fa-times" style="font-size:10px;color:var(--danger);"></i></span></span>';
  }).join('');
}

function handlePackageFiles(input){
  var files=input.files;
  if(!files.length)return;
  
  for(var i=0;i<files.length;i++){
    var file=files[i];
    /* Validate file size (10MB) */
    if(file.size>10*1024*1024){
      showToast(file.name+' exceeds 10MB limit','error');
      continue;
    }
    
    /* Validate file type */
    var allowedTypes=['application/pdf','image/jpeg','image/png'];
    if(allowedTypes.indexOf(file.type)===-1){
      showToast(file.name+' is not a supported file type','error');
      continue;
    }
    
    S.tempPackageFiles.push({
      name:file.name,
      size:file.size,
      type:file.type,
      id:Date.now()+i
    });
  }
  
  renderPackageFiles();
  input.value='';
}

function removePackageFile(id){
  S.tempPackageFiles=S.tempPackageFiles.filter(function(f){return f.id!==id;});
  renderPackageFiles();
}

function renderPackageFiles(){
  var container=document.getElementById('pkg-files-list');
  container.innerHTML=S.tempPackageFiles.map(function(f){
    return'<div class="file-item"><div class="file-icon"><i class="fas '+getFileIcon(f.name)+'"></i></div>'+
    '<div class="flex-1"><div class="text-sm font-medium">'+f.name+'</div><div class="text-xs text-[var(--text2)]">'+formatFileSize(f.size)+'</div></div>'+
    '<button type="button" class="btn-icon danger" onclick="removePackageFile('+f.id+')"><i class="fas fa-times"></i></button></div>';
  }).join('');
}

function togglePackagePreview(){
  var section=document.getElementById('pkg-preview-section');
  var preview=document.getElementById('pkg-preview');
  
  if(section.classList.contains('hidden')){
    section.classList.remove('hidden');
    var name=document.getElementById('pkg-name').value||'Package Name';
    var nameAr=document.getElementById('pkg-nameAr').value||name;
    var price=document.getElementById('pkg-price').value||'0';
    var duration=document.getElementById('pkg-duration').value||'Duration';
    var durationAr=document.getElementById('pkg-durationAr').value||duration;
    var desc=document.getElementById('pkg-desc').value||'';
    var descAr=document.getElementById('pkg-descAr').value||desc;
    
    var features=S.tempPackageFeatures.map(function(f){return S.lang==='ar'?f.ar:f.en;});
    
    preview.innerHTML='<div class="text-center mb-4"><h4 class="text-xl font-bold">'+(S.lang==='ar'?nameAr:name)+'</h4>'+
    (S.lang==='ar'&&descAr?'<p class="text-sm text-[var(--text2)] mt-1">'+descAr+'</p>':'<p class="text-sm text-[var(--text2)] mt-1">'+desc+'</p>')+
    '</div><div class="text-center mb-4"><span class="text-4xl font-bold gradient-text">'+formatMoney(price)+'</span>'+
    '<div class="text-sm text-[var(--text2)]">'+t('perSession')+' • '+(S.lang==='ar'?durationAr:duration)+'</div></div>'+
    (features.length>0?'<div class="space-y-2">'+features.map(function(f){return'<div class="flex items-center gap-2 text-sm"><i class="fas fa-check text-[var(--success)]"></i>'+f+'</div>';}).join('')+'</div>':'');
  } else {
    section.classList.add('hidden');
  }
}

function validatePackageForm(){
  var valid=true;
  
  /* Name validation */
  var name=document.getElementById('pkg-name');
  var nameMsg=document.getElementById('pkg-name-msg');
  if(!name.value.trim()){
    name.classList.add('error');nameMsg.className='validation-msg error';nameMsg.textContent='Package name is required';
    valid=false;
  } else {
    name.classList.remove('error');nameMsg.className='validation-msg';nameMsg.textContent='';
  }
  
  /* Price validation */
  var price=document.getElementById('pkg-price');
  var priceMsg=document.getElementById('pkg-price-msg');
  if(!price.value||parseFloat(price.value)<0){
    price.classList.add('error');priceMsg.className='validation-msg error';priceMsg.textContent='Valid price is required';
    valid=false;
  } else {
    price.classList.remove('error');priceMsg.className='validation-msg';priceMsg.textContent='';
  }
  
  /* Duration validation */
  var duration=document.getElementById('pkg-duration');
  var durationMsg=document.getElementById('pkg-duration-msg');
  if(!duration.value.trim()){
    duration.classList.add('error');durationMsg.className='validation-msg error';durationMsg.textContent='Duration is required';
    valid=false;
  } else {
    duration.classList.remove('error');durationMsg.className='validation-msg';durationMsg.textContent='';
  }
  
  return valid;
}

async function handlePackageSubmit(e){
  e.preventDefault();
  
  if(!validatePackageForm()){return;}
  
  var editId=document.getElementById('pkg-edit-id').value;
  var durationValue=document.getElementById('pkg-duration').value.trim();
  var pkgData={
    name:document.getElementById('pkg-name').value.trim(),
    nameAr:document.getElementById('pkg-nameAr').value.trim()||document.getElementById('pkg-name').value.trim(),
    description:document.getElementById('pkg-desc').value.trim(),
    descriptionAr:document.getElementById('pkg-descAr').value.trim()||document.getElementById('pkg-desc').value.trim(),
    price:parseFloat(document.getElementById('pkg-price').value),
    duration:durationValue,
    durationAr:document.getElementById('pkg-durationAr').value.trim()||durationValue,
    durationMinutes:durationToMinutes(durationValue),
    features:S.tempPackageFeatures.map(function(f){return f.en;}),
    featuresAr:S.tempPackageFeatures.map(function(f){return f.ar;}),
    status:document.getElementById('pkg-status').value,
    featured:document.getElementById('pkg-featured').checked,
    files:S.tempPackageFiles
  };
  
  try{
    var payload={name:pkgData.name,description:pkgData.description,price:pkgData.price,durationMinutes:pkgData.durationMinutes,features:pkgData.features,attachments:pkgData.files,status:pkgData.status,featured:pkgData.featured};
    if(apiToken()){
      if(editId)await apiRequest('/api/packages/'+editId,{method:'PATCH',body:payload});
      else await apiRequest('/api/packages',{method:'POST',body:payload});
      await refreshMyPackages();
    } else if(editId){
      var index=S.packages.findIndex(function(p){return String(p.id)===String(editId);});
      if(index>-1){pkgData.id=editId;S.packages[index]=pkgData;}
    } else {
      pkgData.id=++S.nextId;S.packages.push(pkgData);
    }
    syncPackagesToDirectory();
    closeModal('package-modal');
    renderTab();
    showToast(editId?'Package updated':'Package created','success');
  }catch(err){showToast(err.message||'Could not save package','error');}
}

function syncPackagesToDirectory(){
  if(!S.user||S.user.role!=='photographer')return;
  var dirPhoto=S.photographers.find(function(p){return p.id===S.user.id;});
  if(dirPhoto){dirPhoto.packages=JSON.parse(JSON.stringify(S.packages));}
}

/* ===== File Upload Drag & Drop ===== */
document.addEventListener('DOMContentLoaded',function(){
  var dropZone=document.getElementById('pkg-file-drop');
  if(dropZone){
    ['dragenter','dragover','dragleave','drop'].forEach(function(eventName){
      dropZone.addEventListener(eventName,function(e){e.preventDefault();e.stopPropagation();});
    });
    dropZone.addEventListener('dragenter',function(){dropZone.classList.add('dragover');});
    dropZone.addEventListener('dragover',function(){dropZone.classList.add('dragover');});
    dropZone.addEventListener('dragleave',function(){dropZone.classList.remove('dragover');});
    dropZone.addEventListener('drop',function(e){
      dropZone.classList.remove('dragover');
      var files=e.dataTransfer.files;
      if(files.length){
        document.getElementById('pkg-files').files=files;
        handlePackageFiles(document.getElementById('pkg-files'));
      }
    });
  }
  
  /* Enter key for feature input */
  var featureInput=document.getElementById('pkg-new-feature');
  if(featureInput){
    featureInput.addEventListener('keydown',function(e){
      if(e.key==='Enter'){e.preventDefault();addPackageFeature();}
    });
  }
});

/* ===== DASHBOARD: CALENDAR ===== */
function renderCalendar(){
  var yr=S.calYear,mn=S.calMonth;
  var mNames=S.lang==='ar'?['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر']:['January','February','March','April','May','June','July','August','September','October','November','December'];
  var dNames=S.lang==='ar'?['سبت','أحد','اثنين','ثلاثاء','أربعاء','خميس','جمعة']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var fd=new Date(yr,mn,1).getDay(),dim=new Date(yr,mn+1,0).getDate(),dip=new Date(yr,mn,0).getDate();
  var td=new Date(),tds=td.getFullYear()+'-'+String(td.getMonth()+1).padStart(2,'0')+'-'+String(td.getDate()).padStart(2,'0');
  var ad=new Set(S.appointments.map(function(a){return a.date;}));
  var days='';
  for(var i=fd-1;i>=0;i--)days+='<div class="cal-day other-month">'+(dip-i)+'</div>';
  for(var d=1;d<=dim;d++){
    var ds=yr+'-'+String(mn+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');
    var cls='cal-day';if(ds===tds)cls+=' today';if(ds===S.selectedDate)cls+=' selected';if(ad.has(ds))cls+=' has-apt';
    days+='<div class="'+cls+'" onclick="selectCalDate(\''+ds+'\')">'+d+'</div>';
  }
  var tc=fd+dim,rem=(7-tc%7)%7;
  for(var i=1;i<=rem;i++)days+='<div class="cal-day other-month">'+i+'</div>';
  var sa=S.selectedDate?S.appointments.filter(function(a){return a.date===S.selectedDate;}):[];
  return'<div class="flex justify-between items-center mb-6"><h2 class="text-2xl font-bold">'+t('navCalendar')+'</h2><button onclick="openAptModal()" class="btn-primary btn-sm"><i class="fas fa-plus mr-1"></i>'+t('addAppointment')+'</button></div>'+
  renderWorkingHoursCard()+
  '<div class="grid grid-cols-1 lg:grid-cols-3 gap-6">'+
  '<div class="lg:col-span-2 card p-6"><div class="flex justify-between items-center mb-5">'+
  '<button onclick="changeMonth(-1)" class="w-9 h-9 rounded-lg border border-[var(--border)] flex items-center justify-center text-[var(--text2)] hover:text-[var(--accent)]"><i class="fas fa-chevron-left"></i></button>'+
  '<h3 class="text-lg font-bold">'+mNames[mn]+' '+yr+'</h3>'+
  '<button onclick="changeMonth(1)" class="w-9 h-9 rounded-lg border border-[var(--border)] flex items-center justify-center text-[var(--text2)] hover:text-[var(--accent)]"><i class="fas fa-chevron-right"></i></button></div>'+
  '<div class="grid grid-cols-7 gap-1 mb-2">'+dNames.map(function(d){return'<div class="text-center text-xs text-[var(--text2)] font-semibold py-2">'+d+'</div>';}).join('')+'</div>'+
  '<div class="grid grid-cols-7 gap-1">'+days+'</div></div>'+
  '<div class="card p-6"><h3 class="font-bold mb-4">'+(S.selectedDate?fmtD(S.selectedDate):t('selectDay'))+'</h3>'+
  (sa.length===0?'<p class="text-[var(--text2)] text-sm">'+t('noAptForDay')+'</p>':
  '<div class="space-y-3">'+sa.map(function(a){return'<div class="p-3 rounded-lg bg-[var(--bg2)] border border-[var(--border)]"><div class="flex justify-between items-center mb-1"><span class="text-sm font-bold text-[var(--accent)]">'+a.time+'</span>'+statusBadge(a.status)+'</div><div class="text-sm font-semibold">'+a.client+'</div><div class="text-xs text-[var(--text2)]">'+a.service+'</div>'+(a.notes?'<div class="text-xs text-[var(--text2)] mt-1 italic">'+a.notes+'</div>':'')+'</div>';}).join('')+'</div>')+
  (S.selectedDate?'<button onclick="openAptModal()" class="btn-primary btn-sm w-full mt-4"><i class="fas fa-plus mr-1"></i>'+t('addAptForDay')+'</button>':'')+
  '</div></div>';
}
function renderWorkingHoursCard(){
  var wh=S.workingHours||[
    {dayOfWeek:1,startTime:'08:00',endTime:'14:00',enabled:true},
    {dayOfWeek:2,startTime:'08:00',endTime:'14:00',enabled:true},
    {dayOfWeek:3,startTime:'08:00',endTime:'14:00',enabled:true},
    {dayOfWeek:4,startTime:'08:00',endTime:'14:00',enabled:true},
    {dayOfWeek:5,startTime:'08:00',endTime:'14:00',enabled:true}
  ];
  var labels=S.lang==='ar'?['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت']:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  return'<div class="card p-5 mb-6"><div class="flex flex-wrap items-center justify-between gap-3 mb-4"><div><h3 class="font-bold">'+(S.lang==='ar'?'ساعات العمل':'Working Hours')+'</h3><p class="text-xs text-[var(--text2)]">'+(S.lang==='ar'?'هذه الساعات تحدد المواعيد المتاحة للحجز الفوري':'These hours control instant booking availability')+'</p></div><button onclick="saveWorkingHours()" class="btn-primary btn-sm">'+t('save')+'</button></div>'+
  '<div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">'+[0,1,2,3,4,5,6].map(function(day){
    var item=wh.find(function(x){return Number(x.dayOfWeek)===day;})||{dayOfWeek:day,startTime:'08:00',endTime:'14:00',enabled:false};
    return'<div class="p-3 rounded-lg bg-[var(--bg2)] border border-[var(--border)]"><label class="flex items-center gap-2 text-sm font-semibold mb-2"><input type="checkbox" class="wh-enabled" data-day="'+day+'" '+(item.enabled?'checked':'')+'> '+labels[day]+'</label><div class="grid grid-cols-2 gap-2"><input type="time" class="input wh-start" data-day="'+day+'" value="'+item.startTime+'"><input type="time" class="input wh-end" data-day="'+day+'" value="'+item.endTime+'"></div></div>';
  }).join('')+'</div></div>';
}
async function saveWorkingHours(){
  var rows=[];
  document.querySelectorAll('.wh-enabled').forEach(function(chk){
    var day=Number(chk.dataset.day);
    rows.push({
      dayOfWeek:day,
      enabled:chk.checked,
      startTime:(document.querySelector('.wh-start[data-day="'+day+'"]')||{}).value||'08:00',
      endTime:(document.querySelector('.wh-end[data-day="'+day+'"]')||{}).value||'14:00'
    });
  });
  S.workingHours=rows;
  try{
    if(apiToken())await apiRequest('/api/availability/working-hours',{method:'PUT',body:{workingHours:rows}});
    showToast(S.lang==='ar'?'تم حفظ ساعات العمل':'Working hours saved','success');
  }catch(err){showToast(err.message||'Could not save working hours','error');}
}
function changeMonth(dir){S.calMonth+=dir;if(S.calMonth>11){S.calMonth=0;S.calYear++;}if(S.calMonth<0){S.calMonth=11;S.calYear--;}S.selectedDate=null;renderTab();}
function selectCalDate(ds){S.selectedDate=ds;renderTab();}
function openAptModal(){
  document.getElementById('apt-time').innerHTML=timeSlots().map(function(s){return'<option value="'+s+'">'+s+'</option>';}).join('');
  document.getElementById('apt-service').innerHTML=S.packages.map(function(p){return'<option value="'+gf(p,'name')+'">'+gf(p,'name')+'</option>';}).join('');
  var today = new Date().toISOString().split('T')[0];
  document.getElementById('apt-date').min = today;
  document.getElementById('apt-date').value = S.selectedDate || today;
  openModal('apt-modal');
}
function handleAddApt(e){
  e.preventDefault();
  S.appointments.push({id:++S.nextId,date:document.getElementById('apt-date').value,
    time:document.getElementById('apt-time').value,client:document.getElementById('apt-client').value,
    service:document.getElementById('apt-service').value,notes:document.getElementById('apt-notes').value,status:'confirmed'});
  S.selectedDate=document.getElementById('apt-date').value;
  closeModal('apt-modal');renderTab();showToast('Appointment added','success');
}

