  if(timeArea){timeArea.classList.add('hidden');}
  if(serviceId){
    var serviceSelect=document.getElementById('pub-service');
    if(serviceSelect){serviceSelect.value=String(serviceId);}
    onPubServiceChange();
  }
  var selector=document.getElementById('shoot-type-selector');
  if(selector){selector.querySelectorAll('button').forEach(function(btn){btn.classList.remove('active');});}
